for i,g in enumerate(guides,1):
 steps='<ol class="steps">'+''.join('<li><h3>'+esc(s['label'])+'</h3><p>'+esc(s['detail'])+'</p></li>' for s in g['steps'])+'</ol>'
 panels=''.join('<article><h3>'+label+'</h3>'+lis(g[key])+'</article>' for key,label in [('fieldRules','Field rules'),('primaryActions','Actions'),('controlChecks','Control checks'),('outputs','Expected outputs')])
 sections.append(f'<section id="{esc(g["id"])}" data-guide><p class="eyebrow">{i:02d} / {esc(g["eyebrow"])}</p><h2>{esc(g["title"])}</h2><p class="route">Workspace: {esc(g["route"])}</p><p class="lead">{esc(g["summary"])}</p><h3>{esc(g["flowTitle"])}</h3>{steps}<div class="panels">{panels}</div><p class="related">Related workspaces: '+ ' · '.join(esc(x) for x in g['relatedRoutes'])+'</p></section>')
sections.append('<section id="release"><p class="eyebrow">Client review and release</p><h2>Acceptance before sign-off</h2><p>'+esc(intro)+'</p><h3>Outstanding release gates</h3>'+lis(limits)+'<h3>Witnessed acceptance checklist</h3>'+''.join('<article class="check"><h3>□ '+esc(t)+'</h3><p>'+esc(v)+'</p><p class="sign">Evidence / reviewer / date: ___________________________________</p></article>' for t,v in acceptance)+'</section>')
nav='<a href="#changes">What changed</a>'+''.join(f'<a href="#{esc(g["id"])}">{esc(g["title"])}</a>' for g in guides)+'<a href="#release">Release checklist</a>'
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7f6;color:#203139;font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#17645f}header{padding:64px max(24px,calc((100vw - 1200px)/2));background:#173c3b;color:#fff}header h1{max-width:800px;font-size:clamp(34px,5vw,58px);line-height:1.1;letter-spacing:-.045em;margin:18px 0}header p{max-width:780px;color:#d6e6e3}.eyebrow,.label{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#37726d}.edition{font-size:12px;color:#b9d4cf}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:40px;max-width:1280px;margin:auto;padding:32px 24px}aside{position:sticky;top:20px;align-self:start;max-height:95vh;overflow:auto}aside input{width:100%;padding:12px;border:1px solid #ccd7d4;border-radius:8px;background:#fff;font:inherit}nav{display:grid;margin-top:16px}nav a{padding:8px 10px;font-size:13px;text-decoration:none;border-radius:6px}nav a:hover,nav a:focus-visible{background:#e2eeea}section{scroll-margin-top:24px;margin-bottom:30px;padding:32px;border:1px solid #dce4e1;border-radius:16px;background:#fff}h2{font-size:30px;line-height:1.2;letter-spacing:-.03em;margin:10px 0 18px}h3{font-size:17px;line-height:1.4;margin:20px 0 8px}.route{font:12px ui-monospace,monospace;color:#5b746d;overflow-wrap:anywhere}.lead{font-size:17px;color:#4d625d}.changes,.panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.changes article,.panels article{padding:18px;background:#f6f8f7;border-radius:10px}.changes h3,.panels h3{margin-top:0}.label{margin-bottom:4px}.label+p{margin-top:0;font-size:14px}ul{padding-left:20px}li{margin:8px 0}.steps{padding-left:26px}.steps li{padding-left:8px;margin:20px 0}.steps h3{margin:0}.steps p{margin:5px 0}.related{padding-top:18px;border-top:1px solid #dce4e1;font-size:12px;overflow-wrap:anywhere}.check{border-bottom:1px solid #dce4e1;padding:10px 0 20px}.sign{color:#70817a;font-size:12px}footer{padding:30px;text-align:center;color:#63766f;font-size:12px}[hidden]{display:none!important}button{padding:10px 16px;border:1px solid #bfd3cc;border-radius:8px;background:white;color:#204942;cursor:pointer}@media(max-width:850px){.layout{display:block;padding:16px}aside{position:static;max-height:260px;margin-bottom:24px}section{padding:22px}.panels,.changes{grid-template-columns:1fr}header{padding:36px 24px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;font-size:10pt}header{background:white;color:#173c3b;padding:0}header p,.edition{color:#536c64}aside,button{display:none}.layout{display:block;padding:0}section{border:0;border-radius:0;break-before:page;padding:0}.changes article,.panels article{break-inside:avoid}h2,h3{break-after:avoid}footer{display:none}}'''
