styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Cover',fontName='Helvetica-Bold',fontSize=34,leading=39,textColor=colors.HexColor('#173c3b'),spaceAfter=24));styles.add(ParagraphStyle(name='Title2',fontName='Helvetica-Bold',fontSize=23,leading=28,textColor=colors.HexColor('#173c3b'),spaceAfter=14));styles.add(ParagraphStyle(name='Kicker',fontSize=9,leading=13,textColor=colors.HexColor('#39766b'),spaceAfter=12));styles['BodyText'].fontSize=9.5;styles['BodyText'].leading=12.5;styles['BodyText'].spaceAfter=4;styles['Heading3'].fontSize=11;styles['Heading3'].leading=13;styles['Heading3'].textColor=colors.HexColor('#1b6259');styles['Heading3'].spaceBefore=6
