def clean(s):return s.replace('·',' / ').replace('—','-').replace('–','-').replace('’',"'").replace('“','"').replace('”','"')
def p(s,style='BodyText'):return Paragraph(esc(clean(s)),styles[style])
def bullet(s):return Paragraph('- '+esc(clean(s)),styles['BodyText'])
